#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
# Any key continues; the rest of a multi-byte key (an arrow) is discarded.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press any key to continue}" "$RESET"
  read -rsn1 _ || true
  read -rsn100 -t 0.05 _ || true
  printf '\n'
}

# confirm "question" is a Y/n gate; Enter (or anything but n) means yes.
confirm() {
  local reply=""
  printf '  %s? %s [Y/n]%s ' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  [[ ! "$reply" =~ ^[Nn] ]]
}

# confirm_default_no "question" is a y/N gate for irreversible actions and for
# going on past a failed check: Enter means no.
confirm_default_no() {
  local reply=""
  printf '  %s? %s [y/N]%s ' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# gq-smoke, up: the phase 2 gate (#7) and spec #38's live acceptance (#48).
# Generates the throwaway content site gq-smoke with the published `gq new`,
# verifies it, provisions it with the existing gq commands (the Frontend's
# secrets, the CMS's event key and retry crontab, independent media among
# them), releases it from a `v*` tag through its CI Worker, prepares its
# publication store, passes `gq site check`, and drives the editor-to-visitor
# acceptance against the real CMS and Worker: publication, a shared setting,
# a lost event, a prolonged CMS outage, a withdrawal and a redeploy.
# Tear it down with scripts/smoke/gq-smoke-down.sh.
#
# Run from anywhere: scripts/smoke/gq-smoke-up.sh. Every stage is safe to
# re-run: the gq commands are idempotent and the rest checks before acting.
# Secrets only ever go to Sigillo; the state file holds public values only.

TOTAL_STAGES=22

REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
STATE_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/gq-smoke"
mkdir -p "$STATE_DIR"
ENV_FILE="$STATE_DIR/wizard.env"

PROJECT=gq-smoke
REPOSITORY=Quick-Release/gq-smoke
SIGILLO_API=https://secrets.getquick.io
SIGILLO_ORG=01M2V5A7MYQ1C4482Z3075JZ7C          # GETQUICK
SIGILLO_PROJECT_NAME="GQ Smoke"
# The shared GETQUICK Sigillo project, which holds the account-level secrets.
SHARED_SIGILLO_PROJECT=01M32W12VJR8EDZKGZ4DJP5GK5
# The shared Ploi server, the shared Cloudflare account and the bnq.pt staging zone.
PLOI_SERVER_ID=102329
CF_ACCOUNT_ID=8f38791a8c37b182239af2a385ab3c31
CF_ZONE_ID=60c031fb6f81fae300c625224c39c758
CF_ZONE_NAME=bnq.pt
ADMIN_HOST=$PROJECT-cms.$CF_ZONE_NAME
FRONTEND_HOST=$PROJECT-fe.$CF_ZONE_NAME
MEDIA_HOST=$PROJECT-media.$CF_ZONE_NAME

# site CMD... runs CMD in the generated site's root.
site() { (cd "$SITE_DIR" && "$@"); }

# run CMD... runs CMD in the site root, offering a retry when it fails.
run() {
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  until site "$@"; do
    warn "That failed."
    confirm "Retry?" || { warn "Stopped. Fix it and re-run the wizard: finished stages are skipped or idempotent."; exit 1; }
  done
}

# sig ARGS... runs the site's Sigillo CLI against GETQUICK's Sigillo.
sig() { site ./node_modules/.bin/sigillo "$@" --api-url "$SIGILLO_API"; }

# has_secret ENVIRONMENT NAME: the site's Sigillo environment (gq.ops.json
# name: local, operations or staging) has NAME. Lists names, never values.
# Captured first: with pipefail, grep -q stopping at a match kills the
# listing with SIGPIPE and the pipeline reads as "not found".
has_secret() {
  local names
  names=$(site pnpm --silent exec gq sigillo secrets "$1" 2>/dev/null) || return 1
  grep -qw "$2" <<<"$names"
}

# behind_cloudflare: the CMS host answers through Cloudflare's proxy.
behind_cloudflare() {
  local headers
  headers=$(curl -sSI "https://$ADMIN_HOST/" 2>/dev/null) || return 1
  grep -qi '^server: cloudflare' <<<"$headers"
}

# The project ID of the Sigillo project named $SIGILLO_PROJECT_NAME, if any.
find_sigillo_project() {
  sig projects 2>/dev/null | awk -v want="$SIGILLO_PROJECT_NAME" '
    /^ *- id: "/ { id = $0; gsub(/^ *- id: "|".*$/, "", id) }
    /^ *name: "/ { name = $0; gsub(/^ *name: "|".*$/, "", name); if (name == want) print id }' | head -n1
}

# copy_secret NAME SHARED_ENV SITE_ENV pipes NAME from the shared GETQUICK
# Sigillo project into the site's, never printing it; falls back to a hidden paste.
copy_secret() {
  local name="$1" from="$2" to="$3" value=""
  if has_secret "$to" "$name"; then
    say "$name is already in the site's $to environment; keeping it."
    return
  fi
  value=$(sig secrets get "$name" -p "$SHARED_SIGILLO_PROJECT" --env "$from" --raw --force 2>/dev/null) || value=""
  if [[ -z "$value" ]]; then
    warn "Couldn't read $name from the shared GETQUICK Sigillo project ($from)."
    ask_secret value "Paste $name instead:"
  fi
  [[ -n "$value" ]] || { warn "No value for $name; stopping."; exit 1; }
  printf '%s' "$value" | site pnpm --silent exec gq sigillo secrets "$to" set "$name" >/dev/null
  value=""
  printf '  %s✓ stored%s %s in Sigillo (%s)\n' "$GREEN" "$RESET" "$name" "$to"
}

# registry_accepts ENVIRONMENT: the proxy answers 200 to the Composer login in
# the site's Sigillo ENVIRONMENT (local or staging). Prints nothing secret.
registry_accepts() {
  # shellcheck disable=SC2016 # JavaScript, not shell
  site pnpm --silent exec gq sigillo run "$1" -- node -e '
    const login = JSON.parse(process.env.COMPOSER_AUTH ?? "{}")["http-basic"]?.["proxy.composer.getquick.io"];
    if (!login) process.exit(1);
    const authorization = "Basic " + Buffer.from(`${login.username}:${login.password}`).toString("base64");
    fetch("https://proxy.composer.getquick.io/packages.json", { headers: { authorization } })
      .then((response) => process.exit(response.status === 200 ? 0 : 1), () => process.exit(1));
  ' >/dev/null 2>&1
}

# wait_for_registry ENVIRONMENT: the proxy picks up a new login only once its
# redeploy has propagated, so a Composer install straight after `client add`
# gets HTTP 401. Waits up to two minutes, then offers to keep waiting.
wait_for_registry() {
  local tries=0
  until registry_accepts "$1"; do
    tries=$((tries + 1))
    if (( tries % 24 == 0 )); then
      warn "The registry proxy still rejects the $1 login."
      confirm "Keep waiting?" || exit 1
    fi
    sleep 5
  done
  printf '  %s✓%s the registry proxy accepts the %s login\n' "$GREEN" "$RESET" "$1"
}

# release_tag N: the site's Nth release tag, oldest first, if it exists, so
# a re-run checks an earlier attempt's release instead of cutting another.
release_tag() { site git tag --list 'v*' --sort=v:refname | sed -n "${1}p"; }

# origin_has_certificate: the Ploi server itself serves a valid certificate for
# the CMS host (checked straight at the server, whatever the proxy does).
origin_has_certificate() {
  curl -sS -o /dev/null --max-time 15 --resolve "$ADMIN_HOST:443:$SERVER_IP" "https://$ADMIN_HOST/" 2>/dev/null
}

# ploi_deployed SHA: one of the site's recent Ploi deploy logs ends with the
# deploy script's success line for SHA. The log listing truncates each log,
# so every deploy's full log is fetched.
ploi_deployed() {
  local id log
  for id in $(site pnpm --silent ploi:log 2>/dev/null | node -e '
    let text = ""; process.stdin.on("data", (chunk) => (text += chunk)).on("end", () => {
      const start = text.indexOf("{");
      if (start < 0) return;
      for (const log of JSON.parse(text.slice(start)).data ?? []) if (log.type === "deploy") console.log(log.id);
    });'); do
    log=$(site pnpm --silent ops ploi api sites.get-log-site --path "log=$id" 2>/dev/null) || continue
    grep -q "GQ_SMOKE_DEPLOY_STATUS=success SHA=$1" <<<"$log" && return 0
  done
  return 1
}

# check_hosts SITE_TITLE: the CMS's /wp/graphql reports SITE_TITLE, and the
# Frontend serves the <title> that CMS content implies (its front page's
# title, else the site title), so it is rendering the CMS live.
check_hosts() {
  # shellcheck disable=SC2016 # JavaScript, not shell
  ADMIN_HOST="$ADMIN_HOST" FRONTEND_HOST="$FRONTEND_HOST" node --input-type=module -e '
    const [title] = process.argv.slice(1);
    const { ADMIN_HOST: admin, FRONTEND_HOST: frontend } = process.env;
    const ok = (text) => console.log(`  ✓ ${text}`);
    const bad = (text) => { console.log(`  ⚠ ${text}`); process.exitCode = 1; };
    let data;
    try {
      const response = await fetch(`https://${admin}/wp/graphql`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: "{ generalSettings { title } nodeByUri(uri: \"/\") { ... on Page { title } } }" }),
      });
      data = (await response.json()).data;
    } catch (error) {
      bad(`CMS: https://${admin}/wp/graphql failed: ${error.message}`);
    }
    const siteTitle = data?.generalSettings?.title;
    if (siteTitle === title) ok(`CMS: https://${admin}/wp/graphql reports the site title "${title}"`);
    else if (data) bad(`CMS: /wp/graphql reports the site title "${siteTitle}", not "${title}"`);
    const expected = data?.nodeByUri?.title || siteTitle;
    if (expected) {
      const html = await fetch(`https://${frontend}/`).then((response) => response.text(), () => "");
      const served = (html.match(/<title>([^<]*)<\/title>/u)?.[1] ?? "")
        .replace(/&#39;|&apos;/gu, String.fromCharCode(39))
        .replace(/&quot;/gu, String.fromCharCode(34))
        .replace(/&lt;/gu, "<").replace(/&gt;/gu, ">").replace(/&amp;/gu, "&");
      if (served.startsWith(expected)) ok(`Frontend: https://${frontend} renders "${expected}" from the CMS`);
      else bad(`Frontend: https://${frontend} serves the title "${served}", not "${expected}" from the CMS`);
    }
  ' "$1"
}

# ci_state: "busy" while a CI Workflow run is queued or running, "idle" when
# the listing shows none, "unknown" when listing failed (keep waiting then).
ci_state() {
  local out
  out=$(site pnpm --silent ci:runs 2>/dev/null) || { echo unknown; return; }
  if grep -qE "Running|Queued|Waiting|Paused" <<<"$out"; then echo busy
  elif grep -q "Instance ID" <<<"$out"; then echo idle
  else echo unknown; fi
}

# wait_for_release TAG: waits for the push's CI runs to start (GitHub →
# Artifacts mirror → CI takes a little while) and then to finish, then checks
# Ploi deployed exactly the tagged commit.
wait_for_release() {
  local tag="$1" sha polls=0
  sha=$(site git rev-parse "$tag^{commit}")
  say "The push started CI for $tag ($sha). A tag run checks, then deploys the CMS and the Frontend."
  note "It takes several minutes (checks, then the Ploi and Frontend deploys); polling every 20 seconds."
  until [[ "$(ci_state)" == busy ]] || (( polls >= 9 )); do polls=$((polls + 1)); sleep 20; done
  polls=0
  while [[ "$(ci_state)" != idle ]]; do
    polls=$((polls + 1))
    if (( polls % 90 == 0 )); then
      warn "CI is still running after $((polls / 3)) minutes."
      confirm "Keep waiting?" || break
    fi
    sleep 20
  done
  run pnpm --silent ci:runs
  if ploi_deployed "$sha"; then
    printf '  %s✓%s Ploi deployed %s (%s)\n' "$GREEN" "$RESET" "$tag" "$sha"
  else
    warn "Ploi's recent deploy logs don't show GQ_SMOKE_DEPLOY_STATUS=success SHA=$sha."
    note "Read them with: (cd $SITE_DIR && pnpm ploi:log). The CI run's logs are in the dashboard:"
    open_url "https://dash.cloudflare.com/$CF_ACCOUNT_ID/workers/services/view/$PROJECT-ci/production"
    confirm_default_no "Continue anyway?" || exit 1
  fi
}

banner "gq-smoke: generate, verify, provision and release (phase 2 gate)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
say "Checking the tools this run needs."
missing=()
for tool in git gh node pnpm npx php composer curl; do
  command -v "$tool" >/dev/null 2>&1 || missing+=("$tool")
done
if (( ${#missing[@]} )); then
  warn "Missing: ${missing[*]}. Install them and re-run."
  exit 1
fi
gh auth status >/dev/null 2>&1 || { warn "gh isn't logged in: run gh auth login, then re-run."; exit 1; }
GQ_VERSION=$(node -p "require('$REPO_ROOT/package.json').version")
if ! npm view "@getquick/site@$GQ_VERSION" version >/dev/null 2>&1; then
  warn "@getquick/site $GQ_VERSION (this checkout) isn't on npm yet."
  say "The gate proves the published package: release it first (README → Releasing), then re-run."
  exit 1
fi
printf '  %s✓%s tools present; @getquick/site %s is published\n' "$GREEN" "$RESET" "$GQ_VERSION"
ask SITE_DIR "Where should the site live? (default $(dirname "$REPO_ROOT")/$PROJECT)"
SITE_DIR="${SITE_DIR:-$(dirname "$REPO_ROOT")/$PROJECT}"
write_env SITE_DIR "$SITE_DIR"
ask REGISTRY_DIR "Your getquick-registry checkout? (default $(dirname "$REPO_ROOT")/getquick-registry)"
REGISTRY_DIR="${REGISTRY_DIR:-$(dirname "$REPO_ROOT")/getquick-registry}"
[[ -f "$REGISTRY_DIR/package.json" ]] || { warn "No checkout at $REGISTRY_DIR; clone Quick-Release/getquick-registry and re-run."; exit 1; }
write_env REGISTRY_DIR "$REGISTRY_DIR"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "GitHub repository"
if gh repo view "$REPOSITORY" >/dev/null 2>&1; then
  say "$REPOSITORY already exists (kept from an earlier run); reusing it."
else
  say "Creates the private repository $REPOSITORY. It is kept after teardown, for repeat runs."
  confirm "Create $REPOSITORY now?" || { warn "The run needs it; stopping."; exit 1; }
  gh repo create "$REPOSITORY" --private --description "Throwaway GETQUICK content site for blueprint smoke runs (gq new)"
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Generate the site"
if [[ -f "$SITE_DIR/gq.ops.json" ]]; then
  say "$SITE_DIR already has a gq.ops.json; reusing it instead of generating again."
  note "To generate afresh, delete that directory and re-run."
else
  say "Generating $PROJECT with the published @getquick/site $GQ_VERSION, then installing it."
  mkdir -p "$(dirname "$SITE_DIR")"
  (cd "$(dirname "$SITE_DIR")" && npx --yes "@getquick/site@$GQ_VERSION" new "$(basename "$SITE_DIR")" --project "$PROJECT" --variant content)
fi
run pnpm install
