# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Sigillo project"
say "$PROJECT gets its own Sigillo project with the environments dev, ops and staging."
if ! sig me >/dev/null 2>&1; then
  say "Log in to Sigillo for this checkout (device flow, opens the browser)."
  sig login --scope .
fi
SIGILLO_PROJECT_ID=$(find_sigillo_project || true)
if [[ -z "$SIGILLO_PROJECT_ID" ]]; then
  confirm "Create the Sigillo project \"$SIGILLO_PROJECT_NAME\" in the GETQUICK org?" || exit 1
  sig projects create --org "$SIGILLO_ORG" --name "$SIGILLO_PROJECT_NAME"
  SIGILLO_PROJECT_ID=$(find_sigillo_project || true)
fi
if [[ -z "$SIGILLO_PROJECT_ID" ]]; then
  warn "Couldn't find the new project's ID in the listing above."
  ask SIGILLO_PROJECT_ID "Paste the project ID of \"$SIGILLO_PROJECT_NAME\":"
fi
write_env SIGILLO_PROJECT_ID "$SIGILLO_PROJECT_ID"
environments=$(sig environments -p "$SIGILLO_PROJECT_ID")
for pair in dev:Dev ops:Ops staging:Staging; do
  slug=${pair%%:*}
  if grep -q "slug: \"$slug\"" <<<"$environments"; then
    printf '  %s✓%s environment %s exists\n' "$GREEN" "$RESET" "$slug"
  else
    sig environments create -p "$SIGILLO_PROJECT_ID" --name "${pair#*:}" --slug "$slug"
  fi
done
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Fill in gq.ops.json"
say "Writes the site's public values: the Sigillo project, the $CF_ZONE_NAME hosts, the shared"
say "Ploi server and the shared Cloudflare account, and the $PROJECT buckets, Worker and repository."
say "Then gq sync renders the deploy wiring from them. No secrets are written."
# shellcheck disable=SC2016 # JavaScript, not shell
SIGILLO_PROJECT_ID="$SIGILLO_PROJECT_ID" node --input-type=module -e '
  import { readFileSync, writeFileSync } from "node:fs";
  const path = process.argv[1];
  const [project, admin, frontend, media, server, account, zone, zoneName, repository] = process.argv.slice(2);
  const ops = JSON.parse(readFileSync(path, "utf8"));
  const name = project.replace(/-/g, "_");
  Object.assign(ops, {
    sigillo: {
      apiUrl: "https://secrets.getquick.io",
      projectId: process.env.SIGILLO_PROJECT_ID,
      environments: { local: "dev", operations: "ops", staging: "staging" },
    },
    domains: { admin, frontend },
    ploi: {
      serverId: server,
      ...(ops.ploi?.siteId ? { siteId: ops.ploi.siteId } : {}),
      systemUser: project.replace(/-/g, ""),
      projectRoot: "/",
      webDirectory: "/apps/cms/web",
      database: `${name}_staging`,
      envTemplate: "apps/cms/.env.production.example",
      deployScript: "deploy/ploi/admin.sh",
    },
    releases: { bucket: `${project}-releases`, prefix: "admin/" },
    media: { bucket: `${project}-media`, domain: media },
    backups: { bucket: `${project}-releases`, prefix: "db/" },
    local: { adminEmail: "dev@tipme.to" },
    artifacts: { namespace: project, repo: project },
    ci: { worker: `${project}-ci`, backupBucket: `${project}-ci-backups` },
    cloudflare: { accountId: account, zoneId: zone, zoneName },
    github: { repository },
  });
  writeFileSync(path, `${JSON.stringify(ops, null, 2)}\n`);
' "$SITE_DIR/gq.ops.json" "$PROJECT" "$ADMIN_HOST" "$FRONTEND_HOST" "$MEDIA_HOST" \
  "$PLOI_SERVER_ID" "$CF_ACCOUNT_ID" "$CF_ZONE_ID" "$CF_ZONE_NAME" "$REPOSITORY"
printf '  %s✓ wrote%s %s/gq.ops.json\n' "$GREEN" "$RESET" "$SITE_DIR"
run pnpm exec gq sync
run pnpm install
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Shared secrets"
say "Two account-level secrets come from the shared GETQUICK Sigillo project, piped straight into"
say "$PROJECT's (never printed): the Cloudflare token-manager token and the Ploi API token."
copy_secret CLOUDFLARE_TOKEN_MANAGER_API_TOKEN ops operations
copy_secret PLOI_API_TOKEN staging staging
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Composer registry logins"
say "$PROJECT gets its own logins to the GETQUICK Composer registry: client $PROJECT"
say "(staging: CI and Ploi) and $PROJECT-dev (dev: local installs). The registry CLI"
say "stores each as COMPOSER_AUTH in $PROJECT's Sigillo and redeploys the proxy."
note "Needs \`pnpm registry login\` done once in $REGISTRY_DIR."
for pair in staging:staging:$PROJECT dev:local:$PROJECT-dev; do
  IFS=: read -r slug alias client <<<"$pair"
  if has_secret "$alias" COMPOSER_AUTH; then
    say "COMPOSER_AUTH is already in $slug; keeping it."
    continue
  fi
  printf '  %s$ pnpm registry client add %s --project %s --env %s%s\n' "$DIM" "$client" "$SIGILLO_PROJECT_ID" "$slug" "$RESET"
  until (cd "$REGISTRY_DIR" && pnpm registry client add "$client" --project "$SIGILLO_PROJECT_ID" --env "$slug"); do
    warn "That failed: see the registry CLI's message above (not logged in? run pnpm registry login in $REGISTRY_DIR)."
    confirm "Retry?" || exit 1
  done
done
say "Waiting for the registry proxy to accept both logins (its redeploy takes a moment)."
wait_for_registry staging
wait_for_registry local
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Verify locally (acceptance: pnpm verify passes)"
say "Installs the CMS's Composer dependencies from the registry (writing composer.lock),"
say "then runs every check the pre-push hook and CI run."
run pnpm cms:composer
run pnpm verify
printf '  %s✓%s pnpm verify passed\n' "$GREEN" "$RESET"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Push to GitHub"
if [[ -n "$(site git status --porcelain)" ]]; then
  run git add -A
  run git commit -m "feat: generate $PROJECT with gq new ($GQ_VERSION)"
fi
run git branch -M main
site git remote get-url origin >/dev/null 2>&1 || run git remote add origin "https://github.com/$REPOSITORY.git"
if [[ -n "$(site git ls-remote --heads origin main)" ]] && ! site git merge-base --is-ancestor "$(site git ls-remote --heads origin main | cut -f1)" HEAD 2>/dev/null; then
  warn "$REPOSITORY already has a main this checkout doesn't contain (an earlier run's)."
  confirm_default_no "Force-push this site over it?" || exit 1
  tags=$(site git ls-remote --tags --refs origin 'v*' | sed 's|.*refs/tags/||')
  if [[ -n "$tags" ]] && confirm_default_no "Also delete the earlier run's tags ($(tr '\n' ' ' <<<"$tags"))?"; then
    # shellcheck disable=SC2086
    run git push origin --delete $tags
  fi
  run git push --force -u origin main
else
  run git push -u origin main
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "DNS for the CMS host"
server_json=$(site pnpm --silent ops ploi server show --json 2>/dev/null || true)
SERVER_IP=$(grep -oE '"ip": *"[0-9.]+"' <<<"$server_json" | grep -oE '[0-9.]{7,}' | head -n1 || true)
[[ -n "$SERVER_IP" ]] || ask SERVER_IP "Couldn't read the server's IP; paste Ploi server $PLOI_SERVER_ID's IPv4:"
if origin_has_certificate; then
  say "The server already has a valid certificate for $ADMIN_HOST, so its DNS record is in place."
else
  say "ploi provision only requests the Let's Encrypt certificate while $ADMIN_HOST resolves"
  say "straight to the Ploi server, so the record starts DNS only; stage 11 turns the proxy on."
  open_url "https://dash.cloudflare.com/$CF_ACCOUNT_ID/$CF_ZONE_NAME/dns/records"
  step "Add record → Type A → Name: $PROJECT-cms → IPv4 address: $SERVER_IP"
  step "Proxy status: off for now (grey cloud, DNS only) → Save."
  until [[ "$(node -e "require('dns').promises.resolve4('$ADMIN_HOST').then(a => console.log(a.join(' ')), () => {})")" == *"$SERVER_IP"* ]]; do
    warn "$ADMIN_HOST doesn't resolve to $SERVER_IP yet."
    confirm "Check again?" || { warn "Continuing: ploi provision will skip the certificate until it does."; break; }
  done
fi
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Ploi site"
say "Creates the system user, the site $ADMIN_HOST, the database, its .env, the deploy"
say "script and the certificate on the shared Ploi server. It shows the plan and asks first."
run pnpm ploi:provision
if origin_has_certificate; then
  if behind_cloudflare; then
    say "$ADMIN_HOST is already behind Cloudflare's proxy."
  else
    say "The certificate is issued: put $ADMIN_HOST behind Cloudflare's proxy."
    open_url "https://dash.cloudflare.com/$CF_ACCOUNT_ID/$CF_ZONE_NAME/dns/records"
    step "Edit the A record $PROJECT-cms → Proxy status: on (orange cloud) → Save."
    note "Ploi renews the certificate over HTTP through the proxy; the first renewal is due in about 60 days."
    until behind_cloudflare; do
      warn "$ADMIN_HOST isn't answering through Cloudflare yet (DNS caches can take a few minutes)."
      confirm "Check again?" || break
    done
  fi
else
  warn "No valid certificate on the server for $ADMIN_HOST yet: once it resolves to $SERVER_IP,"
  warn "re-run pnpm ploi:provision (or this wizard) to request it, then turn the proxy on."
  confirm_default_no "Continue without it?" || exit 1
fi
pause

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Cloudflare resources"
say "Each command mints its scoped GETQUICK GQ-SMOKE token into Sigillo staging:"
step "deploy-token: the Frontend's Alchemy deploy token"
step "releases: the $PROJECT-releases bucket and its key"
step "media: the $PROJECT-media bucket on https://$MEDIA_HOST, and its key"
step "ploi:media: writes the media key into the Ploi site's .env (S3_UPLOADS_*)"
step "ci: the Artifacts repo, the $PROJECT-ci-backups bucket and the CI deploy token"
step "frontend:secrets: the Frontend's refresh token and event key, generated into Sigillo staging"
step "ploi:events: the event key into the Ploi site's .env, and the every-minute retry crontab"
note "The deploy token includes D1 for the publication store; an older one gains it, keeping its value."
run pnpm cf:deploy-token
run pnpm cf:releases
run pnpm cf:media
run pnpm ploi:media
run pnpm cf:ci
run pnpm frontend:secrets
run pnpm ploi:events
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "GitHub → CI Worker"
say "github:setup stores a webhook secret and asks for a fine-grained GitHub token."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: $PROJECT CI · Resource owner: Quick-Release · Only select repositories: $PROJECT"
step "Permissions: Contents → Read-only, Commit statuses → Read and write → Generate, copy it."
say "Paste it when github:setup asks (hidden). Then ci:deploy deploys $PROJECT-ci with its secrets."
run pnpm github:setup
run pnpm ci:deploy
if [[ -n "$(site git status --porcelain)" ]]; then
  say "Provisioning recorded values in gq.ops.json (the Ploi site ID); committing them."
  run git add -A
  run git commit -m "chore: record $PROJECT's provisioned IDs"
  run git push
fi
pause

# ── 14 ────────────────────────────────────────────────────────────────────
stage "First release"
say "pnpm push minor bumps the version, runs the checks, commits, tags and pushes."
note "The first CMS deploy installs Bedrock only; WordPress is installed in the next stage."
FIRST_TAG=$(release_tag 1)
if [[ -n "$FIRST_TAG" ]]; then
  say "$FIRST_TAG is already released (an earlier attempt); checking its CI run and deploy."
else
  run pnpm push minor
  FIRST_TAG=$(release_tag 1)
fi
wait_for_release "$FIRST_TAG"
pause

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Install WordPress"
open_url "https://$ADMIN_HOST/wp/wp-admin/install.php"
step "Site title: something unique, e.g. GQ Smoke $(date +%Y-%m-%d) — the last stage looks for it on both hosts."
step "Pick an admin user and a strong password (keep them in your password manager) → Install WordPress."
SMOKE_MARKER=""
until [[ -n "$SMOKE_MARKER" ]]; do
  ask SMOKE_MARKER "The Site title you entered:"
  case "$SMOKE_MARKER" in
    "" | "Content is on its way." | "The front page is almost ready." | GqSmoke)
      warn "That's the Frontend's placeholder text, not a site title; type the title from the install form."
      SMOKE_MARKER="" ;;
  esac
done
write_env SMOKE_MARKER "$SMOKE_MARKER"
pause

# ── 16 ────────────────────────────────────────────────────────────────────
stage "Second release and confirm on the hosts"
say "Now WordPress is installed, this release's deploy activates the theme and plugins (WPGraphQL among them)."
SECOND_TAG=$(release_tag 2)
if [[ -n "$SECOND_TAG" ]]; then
  say "$SECOND_TAG is already released (an earlier attempt); checking its CI run and deploy."
else
  run pnpm push fix
  SECOND_TAG=$(release_tag 2)
fi
wait_for_release "$SECOND_TAG"
say "The Frontend serves only what its publication store holds: until a refresh prepares it,"
say "its pages are a 503. Preparing the whole Site (front page, chrome, every entry)."
until site pnpm frontend:refresh; do
  warn "The refresh didn't store everything (see the report above)."
  confirm "Retry?" || break
done
until check_hosts "$SMOKE_MARKER"; do
  confirm "Re-enter the site title and check again?" || break
  ask SMOKE_MARKER "The Site title (WordPress → Settings → General):"
  write_env SMOKE_MARKER "$SMOKE_MARKER"
done
open_url "https://$FRONTEND_HOST/"
if check_hosts "$SMOKE_MARKER" >/dev/null; then
  say "Phase 2 gate passed: $SECOND_TAG deployed the CMS and the Frontend through Cloudflare CI."
  note "Record it in docs/plans/getquick-blueprint-rollout.md, then tear down: scripts/smoke/gq-smoke-down.sh"
else
  SKIPPED+=("the host checks for $SECOND_TAG failed; the gate hasn't passed")
fi
pause

# ── 17 ────────────────────────────────────────────────────────────────────
stage "Independent media"
say "media:check:upload uploads a probe image through the CMS's REST API, proves it lands"
say "in $PROJECT-media and is served from https://$MEDIA_HOST without the CMS, then deletes it."
say "It signs in as a dedicated Author user with an application password, kept in Sigillo staging."
if has_secret staging CMS_CHECK_USER && has_secret staging CMS_CHECK_APP_PASSWORD; then
  say "CMS_CHECK_USER and CMS_CHECK_APP_PASSWORD are already in Sigillo staging; keeping them."
else
  open_url "https://$ADMIN_HOST/wp/wp-admin/user-new.php"
  step "Username: media-check · Email: any address you own · Role: Author → Add New User."
  step "Users → media-check → Application Passwords → New name: gq media check → Add, copy it."
  ask_secret CMS_CHECK_APP_PASSWORD "Paste the application password (hidden):"
  [[ -n "$CMS_CHECK_APP_PASSWORD" ]] || { warn "No application password; stopping."; exit 1; }
  printf '%s' media-check | site pnpm --silent exec gq sigillo secrets staging set CMS_CHECK_USER >/dev/null
  printf '%s' "$CMS_CHECK_APP_PASSWORD" | site pnpm --silent exec gq sigillo secrets staging set CMS_CHECK_APP_PASSWORD >/dev/null
  CMS_CHECK_APP_PASSWORD=""
  printf '  %s✓ stored%s CMS_CHECK_USER and CMS_CHECK_APP_PASSWORD in Sigillo (staging)\n' "$GREEN" "$RESET"
fi
if site pnpm media:check:upload; then
  say "Independent media proven on $SECOND_TAG; keep the output above as the evidence."
  note "Its outage half runs in stage 21, with an image the acceptance post uses."
else
  SKIPPED+=("pnpm media:check:upload reported the media prerequisite not ready")
fi
pause

# The live acceptance helper, through Sigillo staging (the CMS check user and
# the event key); its state file keeps only public values between stages.
ACCEPTANCE="$REPO_ROOT/scripts/smoke/live-acceptance.mjs"
accept() {
  printf '  %s$ live-acceptance %s%s\n' "$DIM" "$*" "$RESET"
  site env GQ_SMOKE_ACCEPTANCE="$STATE_DIR/acceptance.json" \
    pnpm --silent exec gq sigillo run staging -- node "$ACCEPTANCE" "$@"
}
# acceptance LABEL ARGS...: an acceptance step, offering a retry; a failure
# that isn't retried is carried into the closing summary.
acceptance() {
  local label="$1"
  shift
  until accept "$@"; do
    warn "$label: not as expected (✗ above)."
    confirm "Retry this check?" || { SKIPPED+=("live acceptance: $label failed"); return 1; }
  done
}
ploi_site() { site pnpm --silent ops ploi api "sites.$1-site" --yes >/dev/null; }

# ── 18 ────────────────────────────────────────────────────────────────────
stage "Readiness gate (gq site check)"
say "One gate for the resilience guarantee: the CMS's WPGraphQL schema, the Frontend's"
say "bindings and prepared store, the CMS's scheduler reconciling, the CMS's event key and"
say "crontab, and independent media with an upload. A running Worker or HTTP 200 isn't enough."
note "The first reconciliation comes with the cron's next minute after the second release."
until site pnpm site:check; do
  warn "Not ready yet: each ✗ above says what to run."
  confirm "Check again (after fixing, or a minute for the scheduler)?" || {
    SKIPPED+=("gq site check didn't report ready")
    break
  }
done
pause

# ── 19 ────────────────────────────────────────────────────────────────────
stage "Live acceptance: invalid events, a publication, a shared setting"
say "Invalid events and an unauthenticated refresh are refused by the real Worker; then the"
say "media-check Author uploads an image and publishes a post with it through the REST API."
acceptance "invalid events" refused
acceptance "publication" publish
TAGLINE="Acceptance tagline $(date +%H%M%S)"
open_url "https://$ADMIN_HOST/wp/wp-admin/options-general.php"
step "Settings → General → Tagline: $TAGLINE → Save Changes."
pause "Press any key once it's saved"
acceptance "shared setting" setting "$TAGLINE"
pause

# ── 20 ────────────────────────────────────────────────────────────────────
stage "Live acceptance: a lost event, caught by reconciliation"
say "A change made with WordPress's publication hook removed sends no event; the CMS's"
say "every-minute scheduler has the Frontend reconcile, within the five-minute target."
step "SSH to the server as the site's user (Ploi → Servers → SSH), then run exactly:"
accept lost || SKIPPED+=("live acceptance: couldn't prepare the lost event")
pause "Press any key right after running it"
acceptance "lost-event reconciliation" lost-wait
pause

# ── 21 ────────────────────────────────────────────────────────────────────
stage "Live acceptance: a prolonged CMS outage"
OUTAGE_MINUTES="${GQ_SMOKE_OUTAGE_MINUTES:-15}"
say "Suspends the Ploi site $ADMIN_HOST: the CMS stops answering. Pages, the post and its"
say "image stay served; a page never stored is a 503. Checked again after $OUTAGE_MINUTES minutes"
say "(GQ_SMOKE_OUTAGE_MINUTES), longer than any ordinary cache age; then the CMS is resumed."
confirm "Suspend the CMS now?" || exit 1
ploi_site suspend
acceptance "CMS outage" outage
note "Waiting $OUTAGE_MINUTES minutes; the Frontend reads nothing from the CMS meanwhile."
sleep $((OUTAGE_MINUTES * 60))
acceptance "prolonged outage" prolonged "$OUTAGE_MINUTES"
ploi_site resume
printf '  %s✓%s resumed %s\n' "$GREEN" "$RESET" "$ADMIN_HOST"
pause

# ── 22 ────────────────────────────────────────────────────────────────────
stage "Live acceptance: withdrawal, outage and redeploy"
say "Unpublishing the post makes it a 404 at once; it stays one with the CMS suspended"
say "again and after a Frontend redeploy, which keeps the store. Then the post is deleted."
acceptance "withdrawal" withdraw
ploi_site suspend
acceptance "withdrawal during an outage" withdrawn
ploi_site resume
run pnpm deploy:frontend
acceptance "redeploy preservation" preserved
accept cleanup || SKIPPED+=("delete the acceptance post and image in the CMS by hand")
if (( ${#SKIPPED[@]} == 0 )); then
  say "Spec #38's live acceptance passed on $SECOND_TAG. Record it in the issue, then tear down:"
  note "scripts/smoke/gq-smoke-down.sh"
fi
pause

finish
